import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import { addProductIntent } from 'lib/utils/product-intents'

import { ProductIntentContext } from '~/queries/schema/schema-general'

import { onboardingEventUsageLogic } from '../onboardingEventUsageLogic'
import { GOAL_PRIMARY_PRODUCT, SELF_DRIVING_INTENT_METADATA, type SelfDrivingGoal } from './goals'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface goalSelectionLogicValues {
    selectedGoal: SelfDrivingGoal | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface goalSelectionLogicActions {
    reportSelfDrivingOnboardingGoalSelected: (goal: string) => { goal: string } // onboardingEventUsageLogic
    selectGoal: (goal: SelfDrivingGoal) => { goal: SelfDrivingGoal }
}

export type goalSelectionLogicType = MakeLogicType<goalSelectionLogicValues, goalSelectionLogicActions>

/**
 * Holds the goal declared on the self-driving onboarding's goals step. The selection is intent
 * only for now: later steps will use it to shorten the path to the goal's finish line.
 */
export const goalSelectionLogic = kea<goalSelectionLogicType>([
    path(['scenes', 'onboarding', 'self-driving', 'goalSelectionLogic']),

    connect(() => ({
        actions: [onboardingEventUsageLogic, ['reportSelfDrivingOnboardingGoalSelected']],
    })),

    actions({
        selectGoal: (goal: SelfDrivingGoal) => ({ goal }),
    }),

    reducers({
        selectedGoal: [
            null as SelfDrivingGoal | null,
            // Persisted so a refresh (or the GitHub OAuth round-trip on the install step) keeps
            // the goal-conditional steps in the flow.
            { persist: true },
            {
                selectGoal: (_, { goal }) => goal,
            },
        ],
    }),

    listeners(({ actions }) => ({
        selectGoal: ({ goal }) => {
            actions.reportSelfDrivingOnboardingGoalSelected(goal)
            // The declared goal is the primary intent - activation reporting should attribute this
            // user to the product their goal is about, not to a fixed default.
            void addProductIntent({
                product_type: GOAL_PRIMARY_PRODUCT[goal],
                intent_context: ProductIntentContext.ONBOARDING_PRODUCT_SELECTED_PRIMARY,
                metadata: SELF_DRIVING_INTENT_METADATA,
            })
        },
    })),
])
